def get_role_context(position):
    if type(position) is not int or position not in _ROLES:
        return None
    return {"position": position, "classification": "practice_guidance_not_match_evidence",
            **deepcopy(_ROLES[position]), "limits": [
                "Позиция выбрана игроком; название героя не подтверждает его роль.",
                "Это вопросы и план практики. Они не подтверждают в этом матче контроль рун, обзор, отводы, безопасность союзника или созданное пространство.",
                "Успех роли нельзя установить по одному счётчику. Для проверки помощи союзнику нужен соответствующий эпизод реплея.",
            ]}
